#include "powder/gpu.hpp"
#include <cmath>
#include <iostream>
#include <algorithm>
using namespace powder;
void check(bool v,const char* s){if(!v)throw std::runtime_error(s);}
int main(){try{std::vector<Particle> particles;std::vector<unsigned> groups;for(unsigned i=0;i<513;++i){Particle p;p.id=i+1;p.diameter_m=.002+(i%3)*.0001;p.material.density_kg_m3=1000+(i%2)*500;p.position_m={double(i%17)*.01,double(i/17)*.01,.5};p.velocity_m_s={.01,-.02,.03};p.angular_velocity_rad_s={1,2,3};particles.push_back(p);groups.push_back(i%2);}particles[0].position_m={0,0,0.};particles[1].position_m={.2,.4,1.};particles[2].position_m={-.01,0,.5};GpuSpheres gpu;gpu.reset(particles);MaterialContact m;m.law=ContactLaw::Linear;m.linear={1000,.01,250,.0025,.4};gpu.enable_contacts(m);GpuObservationConfig c;c.lower={0,0,0};c.upper={.2,.4,1};c.grid={2,4,2};gpu.set_observation(c,groups);
 auto audit=[&](){auto actual=gpu.observe();auto state=gpu.snapshot();std::vector<GpuCell> expected(17);double mass=0,energy=0;Vec3 momentum;for(std::size_t i=0;i<state.size();++i){auto p=state[i];auto prop=sphere_properties(p.diameter_m,p.material);mass+=prop.mass_kg;momentum.x+=prop.mass_kg*p.velocity_m_s.x;momentum.y+=prop.mass_kg*p.velocity_m_s.y;momentum.z+=prop.mass_kg*p.velocity_m_s.z;energy+=.5*(prop.mass_kg*(p.velocity_m_s.x*p.velocity_m_s.x+p.velocity_m_s.y*p.velocity_m_s.y+p.velocity_m_s.z*p.velocity_m_s.z)+prop.inertia_kg_m2*(p.angular_velocity_rad_s.x*p.angular_velocity_rad_s.x+p.angular_velocity_rad_s.y*p.angular_velocity_rad_s.y+p.angular_velocity_rad_s.z*p.angular_velocity_rad_s.z));auto v=p.position_m;unsigned bin=16;if(v.x>=0&&v.x<=.2&&v.y>=0&&v.y<=.4&&v.z>=0&&v.z<=1){unsigned x=std::min(1u,unsigned(v.x/.2*2)),y=std::min(3u,unsigned(v.y/.4*4)),z=std::min(1u,unsigned(v.z*2));bin=x+2*(y+4*z);}++expected[bin].count[groups[i]];expected[bin].mass[groups[i]]+=prop.mass_kg;}check(actual.count==513&&std::abs(actual.mass_kg-mass)<mass*1e-12,"total reduction");check(std::abs(actual.kinetic_j-energy)<1e-16&&std::abs(actual.momentum.z-momentum.z)<1e-16,"momentum/energy reduction");actual.cells.push_back(actual.outside);for(unsigned i=0;i<17;++i)for(unsigned g=0;g<2;++g)check(actual.cells[i].count[g]==expected[i].count[g]&&std::abs(actual.cells[i].mass[g]-expected[i].mass[g])<1e-15,"cell/group/outside mismatch");};audit();gpu.advance_contacts(1e-7,20);audit();auto clone=gpu.clone();check(clone->observe().count==513,"clone observation lost");bool rejected=false;try{auto invalid=c;invalid.upper.x=0;gpu.set_observation(invalid,groups);}catch(const std::invalid_argument&){rejected=true;}check(rejected,"invalid observer accepted");audit();std::cout<<"PASS GPU mass/momentum/energy/cell groups/boundaries/outside/clone reductions\n";}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
